/*
 AGROSMART - WF3 / S4-02
 Validar consulta NDVI

 Acepta:
 1. bbox: [oeste, sur, este, norte]
 2. lat y lon: coordenadas de un punto

 Devuelve la solicitud compatible con Sentinel Hub.
*/

const entrada = $input.first().json.body ?? {};

const error = (codigo, mensaje) => [{
  json: {
    valido: false,
    estado: "error",
    codigo,
    mensaje
  }
}];

const numero = v => {
  if (v === null || v === undefined || v === "") {
    return null;
  }

  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

let bbox = null;
let tipoConsulta = null;

// ========================================
// 1. ACEPTAR BBOX O LAT/LON
// ========================================

if (Array.isArray(entrada.bbox)) {

  if (entrada.bbox.length !== 4) {
    return error(
      "BBOX_INVALIDO",
      "bbox debe tener 4 coordenadas."
    );
  }

  bbox = entrada.bbox.map(numero);
  tipoConsulta = "area";

} else {

  const lat = numero(entrada.lat);
  const lon = numero(entrada.lon);

  if (lat === null || lon === null) {
    return error(
      "COORDENADAS_FALTANTES",
      "Envía bbox o las coordenadas lat y lon."
    );
  }

  // Área aproximada de 5 km por lado.
  const mitadKm = 2.5;
  const deltaLat = mitadKm / 111.32;

  const cosLat = Math.cos(lat * Math.PI / 180);

  if (
    Math.abs(lat) > 89 ||
    Math.abs(cosLat) < 0.01
  ) {
    return error(
      "LATITUD_INVALIDA",
      "Latitud no admitida para consulta puntual."
    );
  }

  const deltaLon =
    mitadKm / (111.32 * Math.abs(cosLat));

  bbox = [
    lon - deltaLon,
    lat - deltaLat,
    lon + deltaLon,
    lat + deltaLat
  ];

  tipoConsulta = "punto";
}

// ========================================
// 2. VALIDAR COORDENADAS
// ========================================

const [oeste, sur, este, norte] = bbox;

if (
  bbox.some(v => v === null) ||
  oeste < -180 ||
  este > 180 ||
  sur < -90 ||
  norte > 90 ||
  oeste >= este ||
  sur >= norte
) {
  return error(
    "COORDENADAS_INVALIDAS",
    "Las coordenadas geográficas no son válidas."
  );
}

// Limitar extensión para evitar consultas grandes.
if (
  este - oeste > 0.5 ||
  norte - sur > 0.5
) {
  return error(
    "AREA_DEMASIADO_GRANDE",
    "Selecciona una zona de máximo 0.5 grados por lado."
  );
}

// ========================================
// 3. VALIDAR FECHAS
// ========================================

const inicio = String(entrada.fecha_inicio ?? "");
const fin = String(entrada.fecha_fin ?? "");

const formato = /^\d{4}-\d{2}-\d{2}$/;

if (!formato.test(inicio) || !formato.test(fin)) {
  return error(
    "FECHAS_INVALIDAS",
    "Envía fecha_inicio y fecha_fin en formato YYYY-MM-DD."
  );
}

const fechaInicio = Date.parse(inicio + "T00:00:00Z");
const fechaFin = Date.parse(fin + "T00:00:00Z");

if (
  !Number.isFinite(fechaInicio) ||
  !Number.isFinite(fechaFin) ||
  new Date(fechaInicio).toISOString().slice(0, 10) !== inicio ||
  new Date(fechaFin).toISOString().slice(0, 10) !== fin ||
  fechaInicio > fechaFin ||
  fechaFin > Date.now() ||
  fechaFin - fechaInicio > 31 * 86400000
) {
  return error(
    "RANGO_FECHAS_INVALIDO",
    "Consulta un período válido de máximo 31 días hasta hoy."
  );
}

// ========================================
// 4. SCRIPT NDVI SENTINEL-2
// ========================================

const evalscript = `//VERSION=3
function setup() {
  return {
    input: ["B04", "B08", "SCL", "dataMask"],
    output: {
      bands: 4,
      sampleType: "AUTO"
    }
  };
}

function evaluatePixel(s) {
  if (s.dataMask === 0) {
    return [0, 0, 0, 0];
  }

  // Sombras, nubes y nieve.
  if ([3, 8, 9, 10, 11].includes(s.SCL)) {
    return [0, 0, 0, 0];
  }

  const suma = s.B08 + s.B04;

  if (suma <= 0) {
    return [0, 0, 0, 0];
  }

  const ndvi = (s.B08 - s.B04) / suma;

  if (ndvi < 0.2)
    return [0.75, 0.25, 0.15, 1];

  if (ndvi < 0.4)
    return [0.95, 0.75, 0.20, 1];

  if (ndvi < 0.6)
    return [0.45, 0.75, 0.25, 1];

  return [0.10, 0.55, 0.20, 1];
}`;

// ========================================
// 5. PREPARAR PETICIÓN SENTINEL HUB
// ========================================

const solicitud = {
  input: {
    bounds: {
      bbox,
      properties: {
        crs: "http://www.opengis.net/def/crs/EPSG/0/4326"
      }
    },
    data: [{
      type: "sentinel-2-l2a",
      dataFilter: {
        timeRange: {
          from: inicio + "T00:00:00Z",
          to: fin + "T23:59:59Z"
        },
        mosaickingOrder: "leastCC"
      }
    }]
  },
  output: {
    width: 512,
    height: 512,
    responses: [{
      identifier: "default",
      format: {
        type: "image/png"
      }
    }]
  },
  evalscript
};

return [{
  json: {
    valido: true,
    estado: "correcto",
    indicador: "NDVI",
    region: String(entrada.region ?? ""),
    tipo_consulta: tipoConsulta,
    bbox,
    fecha_inicio: inicio,
    fecha_fin: fin,
    solicitud_sentinel: solicitud
  }
}];
